import React from 'react';
import { Box } from '@material-ui/core';
import Chip from '@material-ui/core/Chip';
import InfoIcon from '@material-ui/icons/Info';
import GitHubIcon from '@material-ui/icons/GitHub';
import CallMadeIcon from '@material-ui/icons/CallMade';
import Dialog from '@material-ui/core/Dialog';

class ProjectView extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      open: false,
    };
  }

  handleClose = () => {
    this.setState({ open: false });
  };

  render() {
    const { item } = this.props;

    return (
      <div>
        <Box
          className="project_card"
          boxShadow={2}
          width="330px"
          style={{
            background: 'white',
            borderRadius: '20px',
            margin: '0px 15px 28px 15px',
            paddingBottom: '17px',
            overflow: 'hidden',
            padding: '5px',
          }}
        >
          <img
            alt={item.title}
            src={
              process.env.PUBLIC_URL +
              '/media/portfolio/' +
              item.imgurl
            }
            height="230px"
            width="100%"
          />

          <h2 style={{ textAlign: 'center', margin: 0 }}>
            {item.title}
          </h2>

          <p style={{ textAlign: 'center', height: '60px', overflow: 'hidden' }}>
            {item.intro}
          </p>

          {item.techstack.map((tech, index) => (
            <Chip
              key={index}
              label={tech}
              style={{
                background: '#3f51b5',
                color: '#fff',
                marginLeft: '3px',
              }}
            />
          ))}

          <hr />

          <div style={{ display: 'flex', justifyContent: 'space-around' }}>
            <InfoIcon
              style={{ cursor: 'pointer' }}
              onClick={() => this.setState({ open: true })}
            />

            <a target="_blank" rel="noreferrer" href={item.links.launch}>
              <CallMadeIcon style={{ color: '#000' }} />
            </a>

            <a target="_blank" rel="noreferrer" href={item.links.github}>
              <GitHubIcon style={{ color: '#000' }} />
            </a>
          </div>
        </Box>

        <Dialog open={this.state.open} onClose={this.handleClose}>
          <h1
            style={{
              background: '#2310a0',
              color: '#fff',
              textAlign: 'center',
              padding: '15px 0px',
              margin: 0,
            }}
          >
            {item.title}
          </h1>

          <p style={{ textAlign: 'center' }}>{item.des}</p>

          <ul>
            {item.points &&
              item.points.map((point, i) => <li key={i}>{point}</li>)}
          </ul>

          <button
            style={{
              padding: '5px 9px',
              width: '90px',
              margin: '10px auto',
              display: 'block',
              cursor: 'pointer',
            }}
            onClick={this.handleClose}
          >
            Close
          </button>
        </Dialog>
      </div>
    );
  }
}

export default ProjectView;
