import React from 'react';
import SkillItem from './SkillItem';

class Skills extends React.Component {
  render() {
    return (
      <div
        id="skill"
        style={{ background: '#ccc', padding: '40px 0px', marginBottom: '20px' }}
      >
        <div style={{ width: '800px', textAlign: 'center', margin: 'auto' }}>
          <h2>SKILLS</h2>
          <p style={{ height: '2px', width: '70px', background: 'red', margin: 'auto' }}></p>

          {this.props.resumeData.skills.map((item) => (
            <div key={item.category}>
              <h2>{item.category}</h2>
              <SkillItem skills={item.list} />
            </div>
          ))}
        </div>
      </div>
    );
  }
}

export default Skills;
